#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
#include <cctype>

using namespace std;

int countWords(const string& str) {
    string s = str;
    for (auto& ch : s) {
        if (ch == '_') ch = ' ';
    }
    // trim leading and trailing spaces
    size_t start = s.find_first_not_of(' ');
    size_t end = s.find_last_not_of(' ');
    if (start == string::npos || end == string::npos) {
        return 0;
    }
    s = s.substr(start, end - start + 1);
    // replace multiple spaces with single space
    string result;
    bool inSpace = false;
    for (char ch : s) {
        if (isspace(ch)) {
            if (!inSpace) {
                result += ' ';
                inSpace = true;
            }
        } else {
            result += ch;
            inSpace = false;
        }
    }
    // split by space
    int count = 0;
    size_t pos = 0;
    while ((pos = result.find(' ')) != string::npos) {
        count++;
        result.erase(0, pos + 1);
    }
    if (!result.empty()) count++;
    return count;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    string s;
    cin >> s;
    vector<int> bracePositions;
    bracePositions.push_back(-1);
    for (size_t i = 0; i < s.length(); ++i) {
        if (s[i] == '(' || s[i] == ')') {
            bracePositions.push_back(i);
        }
    }
    int totalCount = 0;
    int maxWordLen = 0;
    size_t i = 1;
    string outsideText = "";
    while (i + 1 < bracePositions.size()) {
        int startIdx = bracePositions[i];
        int endIdx = bracePositions[i + 1];
        string insideStr = s.substr(startIdx + 1, endIdx - startIdx - 1);
        int countWordsInBrace = countWords(insideStr);
        totalCount += countWordsInBrace;
        int prevIdx = bracePositions[i - 1];
        int startOutside = prevIdx + 1;
        int lengthOutside = startIdx - startOutside;
        if (lengthOutside > 0) {
            outsideText += "_" + s.substr(startOutside, lengthOutside);
        }
        i += 2;
    }
    // Append remaining outside text after last brace
    int lastBraceIdx = bracePositions.back();
    if (lastBraceIdx + 1 < (int)s.size()) {
        outsideText += "_" + s.substr(lastBraceIdx + 1);
    }
    // process outsideText
    for (auto& ch : outsideText) {
        if (ch == '_') ch = ' ';
    }
    // trim leading and trailing spaces
    size_t start = outsideText.find_first_not_of(' ');
    size_t end = outsideText.find_last_not_of(' ');
    if (start != string::npos && end != string::npos) {
        outsideText = outsideText.substr(start, end - start + 1);
    } else {
        outsideText.clear();
    }
    // replace multiple spaces with single space
    string cleanedOutside;
    bool inSpace = false;
    for (char ch : outsideText) {
        if (isspace(ch)) {
            if (!inSpace) {
                cleanedOutside += ' ';
                inSpace = true;
            }
        } else {
            cleanedOutside += ch;
            inSpace = false;
        }
    }
    // split outside words
    size_t pos = 0;
    vector<string> outsideWords;
    while ((pos = cleanedOutside.find(' ')) != string::npos) {
        string word = cleanedOutside.substr(0, pos);
        if (!word.empty()) outsideWords.push_back(word);
        cleanedOutside.erase(0, pos + 1);
    }
    if (!cleanedOutside.empty()) outsideWords.push_back(cleanedOutside);
    for (const auto& w : outsideWords) {
        if ((int)w.length() > maxWordLen) {
            maxWordLen = w.length();
        }
    }
    cout << maxWordLen << " " << totalCount;
    return 0;
}

